interface ButtonProps {
  label: string;
  onClick: () => void;
  variant?: "primary" | "secondary";
}

function Button({ label, onClick, variant = "primary" }: ButtonProps) {
  return <button className={variant} onClick={onClick}>{label}</button>;
}

// Compile-time errors, caught before any of this code ever runs:
<Button onClick={() => save()} />           // Error: missing required prop 'label'
<Button label={42} onClick={() => save()} /> // Error: 'label' expects string, got number
<Button label="Save" onClick={save()} />     // Error: onClick expects a function, got whatever save() returns

interface User {
  id: string;
  name: string;
}

function Profile() {
  // Inferred as number -- no annotation needed.
  const [count, setCount] = useState(0);

  // Without an explicit type argument, this would infer as `null`,
  // and a later setUser(realUser) call would be a type error.
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    fetchUser().then((data: User) => setUser(data));
  }, []);

  if (!user) return <p>Loading...</p>;

  // TypeScript now knows user is a User here (not null), because of
  // the early return above -- this is called "narrowing".
  return <h1>{user.name}</h1>;
}

