function ItemList({ items }) {
  const [selectedId, setSelectedId] = useState(null);

  // WITHOUT useCallback: a new function every render would defeat
  // memo below, since every ExpensiveRow would see a "new" onSelect.
  // const handleSelect = (id) => setSelectedId(id);

  // WITH useCallback: a stable reference across renders, since its
  // dependency array (empty here) never changes.
  const handleSelect = useCallback((id) => setSelectedId(id), []);

  return (
    <ul>
      {items.map((item) => (
        <ExpensiveRow key={item.id} item={item} onSelect={handleSelect} />
      ))}
    </ul>
  );
}

